from pathlib import Path
p=Path('admin.html')
s=p.read_text(encoding='utf-8')
marker='TORVO ADMIN STRUCTURAL V23'
if marker not in s:
 css='''<style id="torvo-admin-structural-v23">/* TORVO ADMIN STRUCTURAL V23 */
:root{--v23navy:#102033;--v23red:#ed2638;--v23bg:#f5f7fb;--v23line:#e1e7ef;--v23text:#17243a}
body{background:var(--v23bg)!important}.app{grid-template-columns:238px minmax(0,1fr) 0!important}.right{display:none!important}.left{background:var(--v23navy)!important;color:#fff!important;border:0!important;padding:14px 10px!important}.left .logo{color:#fff!important;font-size:26px!important}.left .sub{color:#9eacbc!important;border-color:#2b3b4f!important}.left .menuTitle{display:none!important}.left .nav{border:0!important;background:transparent!important;color:#dce5ef!important;border-radius:7px!important;margin:2px 0!important;padding:10px 12px!important}.left .nav.active{background:var(--v23red)!important;color:#fff!important}.main{background:var(--v23bg)!important;padding:0 18px 28px!important}.top{margin:0 -18px 14px!important;border-radius:0!important;border:0!important;border-bottom:1px solid var(--v23line)!important;box-shadow:none!important;padding:10px 18px!important;background:#fff!important}.top .title{display:none!important}.top .search input{border:1px solid #d6dee9!important;background:#f8fafc!important}.v23PageHead{display:flex;justify-content:space-between;align-items:center;margin:4px 0 12px}.v23PageHead h1{font-size:20px;margin:0;color:var(--v23text)}.v23PageHead small{display:block;color:#77869a;margin-top:3px}.v23Quick{display:flex;gap:7px;flex-wrap:wrap}.v23Quick button{border:1px solid var(--v23line);background:#fff;border-radius:7px;padding:9px 12px;font-size:9px;font-weight:900;color:#334155}.v23Quick button.primary{background:var(--v23red);color:#fff;border-color:var(--v23red)}.v23Dashboard{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-bottom:10px}.v23Kpi{background:#fff;border:1px solid var(--v23line);border-radius:9px;padding:14px;min-height:92px}.v23Kpi b{display:block;font-size:10px;color:#65748a}.v23Kpi strong{display:block;font-size:25px;margin-top:10px;color:#152238}.v23Work{display:grid;grid-template-columns:minmax(0,2fr) minmax(240px,1fr);gap:10px}.v23WorkCard{background:#fff;border:1px solid var(--v23line);border-radius:9px;padding:13px;min-height:160px}.v23WorkCard h3{font-size:11px;margin:0 0 10px}.v23ActionGrid{display:grid;grid-template-columns:repeat(3,1fr);gap:7px}.v23ActionGrid button{min-height:54px;border:1px solid #dce4ee;border-radius:8px;background:#f9fbfd;font-size:9px;font-weight:900}.panel,.box,.card{border:1px solid var(--v23line)!important;box-shadow:none!important}.section.active{max-height:calc(100vh - 75px)!important;overflow:auto!important}.torvo-ref-tabs{display:flex!important;gap:5px!important;overflow:auto!important;margin:0 0 12px!important;padding:4px!important;background:#fff!important;border:1px solid var(--v23line)!important;border-radius:8px!important}.torvo-ref-tab{flex:0 0 auto!important;border:0!important;border-radius:6px!important;background:#f1f4f8!important;padding:9px 12px!important;font-size:9px!important;font-weight:900!important}.torvo-ref-tab.active{background:var(--v23red)!important;color:#fff!important}
@media(max-width:900px){.v23Dashboard{grid-template-columns:repeat(2,1fr)}.v23Work{grid-template-columns:1fr}}
@media(max-width:640px){.app{display:block!important}.left{height:62px!important;min-height:62px!important;position:sticky!important;top:0!important;z-index:80!important;display:flex!important;align-items:center!important;overflow:hidden!important;padding:7px 9px!important}.left .logo{font-size:21px!important;white-space:nowrap!important}.left .sub,.left .menuTitle,.left .nav{display:none!important}.left .nav.active{display:block!important;margin-left:auto!important;width:auto!important;background:var(--v23red)!important}.main{padding:0 8px 20px!important}.top{top:62px!important;margin:0 -8px 9px!important;padding:7px 8px!important}.top .owner,.top .verifyBtn,.top .logout,.top .langBtn{display:none!important}.v23PageHead{align-items:flex-start;gap:8px}.v23PageHead h1{font-size:17px}.v23Quick{justify-content:flex-end}.v23Quick button:not(.primary){display:none}.v23Dashboard{grid-template-columns:repeat(2,1fr);gap:7px}.v23Kpi{min-height:82px;padding:11px}.v23Kpi strong{font-size:22px}.v23ActionGrid{grid-template-columns:repeat(2,1fr)}.section.active{max-height:none!important;overflow:visible!important}.panel{padding:10px!important}.cards,.grid,.itemGrid,.reportGrid{grid-template-columns:1fr!important}}
</style>'''
 s=s.replace('</head>',css+'\n</head>',1)
 # Insert real reference dashboard structure inside existing dashboard section without removing working legacy IDs.
 dash='''<div id="v23DashboardShell"><div class="v23PageHead"><div><h1>WELCOME BACK, ADMIN!</h1><small>TORVO B2B PORTAL ADMIN PANEL</small></div><div class="v23Quick"><button>DD/MM/YYYY</button><button class="primary" onclick="showSection('additem')">+ ADD PRODUCT</button></div></div><div class="v23Dashboard"><div class="v23Kpi"><b>TOTAL DEALERS</b><strong id="v23Dealers">0</strong></div><div class="v23Kpi"><b>TOTAL PRODUCTS</b><strong id="v23Products">0</strong></div><div class="v23Kpi"><b>TOTAL ORDERS</b><strong id="v23Orders">0</strong></div><div class="v23Kpi"><b>TOTAL ESTIMATES</b><strong id="v23Estimates">0</strong></div></div><div class="v23Work"><div class="v23WorkCard"><h3>QUICK ACTIONS</h3><div class="v23ActionGrid"><button onclick="showSection('additem')">+ ADD SPARE PART</button><button onclick="showSection('itemmaster')">SPARE PARTS</button><button onclick="showSection('machine')">MACHINES</button><button onclick="showSection('reports')">REPORTS</button><button onclick="showSection('settings')">SETTINGS</button><button onclick="showSection('market')">DEALERS</button></div></div><div class="v23WorkCard"><h3>LOW STOCK ALERT</h3><div class="empty">NO LOW STOCK ITEMS</div></div><div class="v23WorkCard"><h3>RECENT ACTIVITY</h3><div class="empty">NO RECENT ACTIVITY</div></div><div class="v23WorkCard"><h3>ORDER STATUS</h3><div class="empty">NO ORDER DATA</div></div></div></div>'''
 # Find dashboard section and prepend new structural dashboard; legacy dashboard remains hidden only inside dashboard.
 import re
 m=re.search(r'(<[^>]+class="[^"]*section[^\"]*"[^>]+id="dashboard"[^>]*>)',s,re.I)
 if not m: m=re.search(r'(<[^>]+id="dashboard"[^>]+class="[^"]*section[^\"]*"[^>]*>)',s,re.I)
 if m:
  s=s[:m.end()]+dash+s[m.end():]
  # Hide legacy direct panels/cards after our shell, dashboard only.
  css2='<style>#dashboard>#v23DashboardShell~*{display:none!important}</style>'
  s=s.replace('</head>',css2+'\n</head>',1)
 # Add approved tabs to actual spare form host.
 if 'id="spareFormHost"' in s and '<div class="torvo-ref-tabs">' not in s:
  tabs='<div class="torvo-ref-tabs"><button type="button" class="torvo-ref-tab active">BASIC DETAILS</button><button type="button" class="torvo-ref-tab">MACHINE FITMENT</button><button type="button" class="torvo-ref-tab">SUITABLE FOR</button><button type="button" class="torvo-ref-tab">PRICING & STOCK</button><button type="button" class="torvo-ref-tab">IMAGES & DOCUMENTS</button><button type="button" class="torvo-ref-tab">ADDITIONAL INFO</button></div>'
  pos=s.find('id="spareFormHost"'); end=s.find('>',pos)
  if end>=0:s=s[:end+1]+tabs+s[end+1:]
p.write_text(s,encoding='utf-8')
